/**
 * WISDOM BANK B — ashtavakra_gita, vivekachudamani, dhammapada.
 */

import type { WisdomArchetype } from "./types";

export const WISDOM_ASHTAVAKRA: WisdomArchetype[] = [
  { concept: "You Are the Witness, Not the Body", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 1.1-1.7", explanation: "The Ashtavakra Gita opens with the direct instruction: you are not the body, not the mind, not the intellect — you are the witness, the pure awareness in which all of these appear. The text wastes no words on preparation; it begins at the destination.", application: "When identity feels heavy with body or mind, apply the opening instruction directly: name what you are aware of, and recognize you are not it.", questions: ["What am I aware of right now — and am I it?", "What is the cost of believing I am the body-mind?", "What remains when every 'I am this' is withdrawn?"], references: ["Ashtavakra Gita 1.1-1.7", "Ashtavakra Gita 2.1-2.6"], excerpt: "You are not the body, not the mind. You are the witness — awareness itself.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "witness", "not_the_body", "direct", "opening"], difficulty: "intermediate", minutes: 5 },
  { concept: "The World Is Appearance — Like a Dream", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 4.1-4.10", explanation: "The world is appearance, like a dream. The Ashtavakra Gita uses the dream analogy relentlessly: in dream, the body and world seem real; on waking, they are seen as mind-made. The waking state is the same structure, one dream longer.", application: "Use the dream analogy as a daily lens: when the day's events feel overwhelmingly real, ask what changes if this too is appearance. Not indifference — clarity.", questions: ["What in today's world feels most solid — and what would 'appearance' mean for it?", "How does the dream analogy change my relationship to conflict?", "What wakes me from the dream, if not another dream?"], references: ["Ashtavakra Gita 4.1-4.10", "Ashtavakra Gita 18.1-18.10"], excerpt: "The world is like a dream — seen as real until waking.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "dream", "appearance", "maya", "analogy"], difficulty: "intermediate", minutes: 6 },
  { concept: "You Are the Space in Which Everything Happens", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 2.1-2.12", explanation: "Like the space in a pot that is not the pot, you are the space in which body and mind happen. Break the pot and the space is unchanged. The Gita's central image: you are the container, never the contained.", application: "When events feel crushing, recall the pot: the space is not damaged by the pot's shape. The practice is to rest as the space, not the shape.", questions: ["Where do I feel like the pot rather than the space?", "What would 'resting as space' change in my next difficult conversation?", "Can I feel the space in which this thought is happening?"], references: ["Ashtavakra Gita 2.1-2.12", "Ashtavakra Gita 5.1-5.10"], excerpt: "You are the space in which everything happens — like the space in the pot, never the pot.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "space", "pot", "container", "unchanged"], difficulty: "intermediate", minutes: 6 },
  { concept: "Bondage and Freedom Are Both Mind-Made", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 1.10-1.15", explanation: "You are not bound, you are not free — bondage and freedom are both mind-made. The one who knows this is free. The Gita refuses the language of progress toward freedom: freedom is not achieved but recognized, when the mind's fabrication of bondage is seen.", application: "Stop asking 'how do I become free' and ask 'what is fabricating bondage right now.' The fabrication is always in the mind — and the mind can be seen through.", questions: ["What am I calling bondage today — and where is it fabricated?", "What would recognition (not achievement) of freedom look like?", "Can I find one moment today when bondage was absent?"], references: ["Ashtavakra Gita 1.10-1.15", "Ashtavakra Gita 19.1-19.10"], excerpt: "You are not bound, you are not free. Bondage and freedom are both mind-made.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "bondage", "freedom", "mind_made", "recognition"], difficulty: "advanced", minutes: 7 },
  { concept: "Desire and Aversion Are the Two Ropes", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 2.13-2.20", explanation: "Desire and aversion are the two ropes that bind you. When you abandon both, you are free. The Gita's diagnosis is symmetrical: it is not desire alone but the pair — the reaching toward and the pushing away — that constitutes the knot.", application: "Watch for the pair in operation: every craving has its shadow aversion. The practice is not to kill desire but to see the pair as one mechanism, and to stop pulling its ropes.", questions: ["What am I reaching toward today — and what is its shadow aversion?", "Where am I pulling both ropes at once?", "What happens when neither rope is pulled?"], references: ["Ashtavakra Gita 2.13-2.20", "Ashtavakra Gita 6.1-6.10"], excerpt: "Desire and aversion are the two ropes. Abandon both, and you are free.", evidence: "traditional", dimensions: ["emotion", "thought"], paths: ["jnana", "raja"], domains: ["growth"], tags: ["ashtavakra", "desire", "aversion", "ropes", "binding"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Mind Is the Only Obstacle", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 1.11-1.12", explanation: "The mind alone is the cause of bondage and liberation. Bonded, it is the world; freed, it is nothing. The Ashtavakra Gita's radical claim: there is no external obstacle. Every obstacle is the mind's own activity, seen as external.", application: "When facing an obstacle, ask: what is the mind doing with this? The obstacle's power is the mind's participation. Withdraw the participation, and the obstacle becomes scenery.", questions: ["What obstacle is my mind currently participating in?", "What would the obstacle be without my mind's commentary?", "Where is the mind creating the world it then suffers?"], references: ["Ashtavakra Gita 1.11-1.12", "Ashtavakra Gita 3.1-3.10"], excerpt: "The mind alone binds; the mind alone frees.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "spirituality"], tags: ["ashtavakra", "mind", "obstacle", "bondage", "liberation"], difficulty: "intermediate", minutes: 6 },
  { concept: "You Are Already Free — Stop Seeking", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 3.1-3.10", explanation: "You are already free. The seeking itself is the bondage. The Gita's most challenging instruction: the one who seeks freedom is already free, and the seeking perpetuates the illusion of bondage. Stop seeking; rest as what you are.", application: "This is the library's counter-practice: not another technique but the cessation of technique-seeking. Try one session with no method — just the recognition that the seeker is the sought.", questions: ["What am I seeking — and who is seeking it?", "What would one session without method feel like?", "Can I distinguish seeking from resting?"], references: ["Ashtavakra Gita 3.1-3.10", "Ashtavakra Gita 20.1-20.10"], excerpt: "You are already free. Stop seeking.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "already_free", "seeking", "cessation", "resting"], difficulty: "advanced", minutes: 7 },
  { concept: "The Sage Is Unconcerned — Not Indifferent", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 5.1-5.15", explanation: "The sage is described as unconcerned — not indifferent. The distinction is precise: indifference is a defense; unconcern is the natural state when nothing is claimed. The sage acts, speaks, lives — without the grip of outcome.", application: "Practice unconcern in one small domain today: do the thing, release the result, and notice the difference between not caring (defense) and being unconcerned (freedom).", questions: ["Where is my 'unconcern' actually indifference in disguise?", "What would genuine unconcern look like in my work?", "Can I act fully while claiming nothing?"], references: ["Ashtavakra Gita 5.1-5.15", "Ashtavakra Gita 17.1-17.10"], excerpt: "The sage is unconcerned — not indifferent, but free of the grip of outcome.", evidence: "traditional", dimensions: ["emotion", "spirit", "action"], paths: ["jnana", "karma"], domains: ["growth", "work"], tags: ["ashtavakra", "sage", "unconcerned", "indifference", "outcome"], difficulty: "advanced", minutes: 7 },
  { concept: "The Body Is a City — You Are Its Ruler, Not Its Worker", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 6.1-6.10", explanation: "The body is a city with nine gates, ruled by the self. The Gita's image: the self governs but does not labor. The city's functions — digestion, breath, thought — proceed without the self's effort. The ruler is not the worker.", application: "When exhaustion comes from feeling responsible for everything, recall the city: the body's processes run without your management. Your role is witnessing, not operating.", questions: ["Where am I trying to run the city's functions myself?", "What happens when I stop managing the unmanageable?", "Can I feel the body's processes running without me?"], references: ["Ashtavakra Gita 6.1-6.10", "Bhagavad Gita 13.1-13.3"], excerpt: "The body is a city of nine gates, ruled by the self that does no work.", evidence: "traditional", dimensions: ["body", "spirit"], paths: ["jnana"], domains: ["health", "spirituality"], tags: ["ashtavakra", "city", "nine_gates", "ruler", "worker"], difficulty: "intermediate", minutes: 6 },
  { concept: "No Practice Is Needed — Only Recognition", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 7.1-7.10", explanation: "The Gita's most radical chapter: no practice is needed, no method, no effort — only recognition. You are the witness, already free; every practice is a concession to the illusion that something must be done. The text holds this position uncompromisingly.", application: "Use this teaching as a periodic check on practice addiction: is this session a practice or a recognition? Both are valid; confusing them is not. The library's practices are ladders; this teaching is the view from the top.", questions: ["Is my practice a ladder or a crutch?", "What would recognition (not practice) look like today?", "Can I hold both — practice for the mind, recognition for the self?"], references: ["Ashtavakra Gita 7.1-7.10", "Ashtavakra Gita 12.1-12.10"], excerpt: "No practice is needed. You are the witness, already free.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "no_practice", "recognition", "radical", "witness"], difficulty: "advanced", minutes: 7 },
  { concept: "The Rope and the Snake — The Classic Analogy", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 8.1-8.10; Advaita tradition", explanation: "The world is like a rope mistaken for a snake. The snake was never real; only the rope was. When the rope is seen, the snake vanishes — not by being destroyed but by being recognized as never having existed. The Gita uses the oldest analogy of Advaita.", application: "Apply the analogy to a current fear: what is the rope (the real situation) and what is the snake (the feared story)? Seeing the rope does not deny the situation; it removes the snake.", questions: ["What snake am I currently mistaking for a rope?", "What is the actual situation — the rope?", "What changes when the snake is seen as never having existed?"], references: ["Ashtavakra Gita 8.1-8.10", "Gaudapada Karika", "Shankara's commentary on Brahma Sutras"], excerpt: "The rope was never a snake. Seeing the rope, the snake vanishes.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "spirituality"], tags: ["ashtavakra", "rope", "snake", "analogy", "illusion"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Ocean and the Waves — You Are the Water", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 9.1-9.10", explanation: "You are the ocean, not the waves. The waves rise and fall — thoughts, emotions, events — but the water is never harmed. The Gita's image of identity: the wave's drama is real as pattern, unreal as self.", application: "In emotional weather, ask: am I the wave or the water? The answer is not to stop waving but to stop drowning in the wave's identity.", questions: ["Which wave am I currently identified with?", "What would 'being the water' feel like in this moment?", "Can the wave be allowed to wave, without me being it?"], references: ["Ashtavakra Gita 9.1-9.10", "Ashtavakra Gita 11.1-11.10"], excerpt: "You are the ocean; the waves are your movements, not your identity.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "ocean", "waves", "water", "identity"], difficulty: "beginner", minutes: 5 },
  { concept: "The Mirror — The World Reflects in You", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 10.1-10.10", explanation: "The world is reflected in you, as the world is reflected in a mirror. The mirror is not stained by what it reflects; the self is not stained by the world. The Gita's image of the untainted witness.", application: "When the world's content feels contaminating — news, conflict, others' pain — recall the mirror: reflection without stain. Compassion remains; contamination does not.", questions: ["What am I mistaking for stain — reflection or identification?", "How do I hold the world's pain without being stained by it?", "What is the difference between reflection and absorption?"], references: ["Ashtavakra Gita 10.1-10.10", "Vivekachudamani"], excerpt: "The world is reflected in you, as in a mirror — the mirror is not stained.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana"], domains: ["spirituality", "relationships"], tags: ["ashtavakra", "mirror", "reflection", "unstained", "witness"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Pot's Space — Breaking the Pot Changes Nothing", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 11.1-11.10", explanation: "The space inside a pot is not born with the pot and does not die with it. Break the pot: the space is unchanged. The Gita's most precise image of the self's relation to the body — the body is a pot; you are the space.", application: "Contemplate the pot with the body: the body's birth and death are the pot's making and breaking. The space — awareness — was never either. This is the library's deepest death teaching.", questions: ["What changes when I take the pot's breaking seriously?", "Can I feel the space that was never born?", "How does this change my relationship to mortality?"], references: ["Ashtavakra Gita 11.1-11.10", "Ashtavakra Gita 2.1-2.12"], excerpt: "The pot's space is not born with the pot, nor dies with it.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "pot", "space", "death", "unchanged"], difficulty: "advanced", minutes: 8 },
  { concept: "The Thief Is the Police — The Mind Polices Itself", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 12.1-12.10", explanation: "The Gita's paradoxical image: the mind is both the thief and the police. It creates the problem and then investigates itself. Liberation is not the mind catching itself — it is the mind being seen as the whole apparatus.", application: "When self-monitoring becomes self-surveillance (the spiritual ego policing its own progress), recall the image: the thief is the police. Stop the apparatus; rest as what was never policed.", questions: ["Where is my mind policing itself today?", "What is the thief it is chasing?", "What is present when the apparatus stops?"], references: ["Ashtavakra Gita 12.1-12.10"], excerpt: "The mind is the thief and the police. See the apparatus, and rest.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "spirituality"], tags: ["ashtavakra", "thief", "police", "mind", "apparatus"], difficulty: "advanced", minutes: 7 },
  { concept: "The Seed and the Tree — No Birth, No Death", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 13.1-13.10", explanation: "The self is not born and does not die — like the space in the pot, like the screen and the film. The Gita's teaching on mortality: birth and death belong to the body's story; the witness attends both without participating.", application: "In the face of loss or mortality, the teaching is not comfort but clarity: what attends was never at risk. Grief is for the body's story; the witness is untouched — and can hold grief fully.", questions: ["What in me attends death without dying?", "How does this teaching change grief — deepen it or bypass it?", "Can I hold both: the story's reality and the witness's untouchedness?"], references: ["Ashtavakra Gita 13.1-13.10", "Bhagavad Gita 2.20"], excerpt: "You are not born, you do not die. You are the witness of both.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "birth", "death", "witness", "mortality"], difficulty: "advanced", minutes: 8 },
  { concept: "The Dreamer Is Not the Dream", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 14.1-14.10", explanation: "You are the dreamer, not the dream. The dream contains the body, the world, the other people, the story of your life. The dreamer is not in the dream — the dream is in the dreamer. The Gita's most portable image.", application: "When the day's story feels all-consuming, ask: who is dreaming this? The question does not dismiss the dream; it relocates you from inside it to its source.", questions: ["What is today's dream containing?", "Who is dreaming it?", "What changes when I rest as the dreamer, not the dream?"], references: ["Ashtavakra Gita 14.1-14.10", "Ashtavakra Gita 4.1-4.10"], excerpt: "You are the dreamer, not the dream. The dream is in you, not you in the dream.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "dreamer", "dream", "source", "portable"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Fire of Knowledge Burns the Karma", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 15.1-15.10", explanation: "Knowledge is described as fire — it burns the karma, the accumulated action's momentum. Not by destroying action but by burning the attachment to its fruits. The fire metaphor: knowledge is not information; it is combustion.", application: "Distinguish knowledge-as-information from knowledge-as-fire. The library's wisdom entries are fuel; the fire is the contemplation that burns attachment. Read, then burn.", questions: ["What am I accumulating — information or fire?", "Where is karma's momentum strongest in my life?", "What would burning attachment to results look like this week?"], references: ["Ashtavakra Gita 15.1-15.10", "Bhagavad Gita 4.37"], excerpt: "Knowledge is fire; it burns karma to ash.", evidence: "traditional", dimensions: ["spirit", "thought", "action"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["ashtavakra", "fire", "knowledge", "karma", "burning"], difficulty: "advanced", minutes: 7 },
  { concept: "The Child's Nature — Uncomplicated Awareness", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 16.1-16.10", explanation: "The Gita describes the natural state as childlike — not childish, but uncomplicated. Before the mind's apparatus of claim and defense, awareness is simple: present, unconcerned, undivided. The teaching values simplicity over sophistication.", application: "Notice the next child's uncomplicated presence — or recall your own earliest memories of pure attention. The state is not regressive; it is the baseline the practices return to.", questions: ["When was I last uncomplicatedly present?", "What does sophistication cost me in presence?", "Can I be childlike about this — curious, unguarded, unclaiming?"], references: ["Ashtavakra Gita 16.1-16.10", "Zen teaching on beginner's mind"], excerpt: "Be like a child — uncomplicated, present, undivided.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana", "zen"], domains: ["growth", "spirituality"], tags: ["ashtavakra", "child", "simplicity", "uncomplicated", "baseline"], difficulty: "beginner", minutes: 5 },
  { concept: "The Sky and the Clouds — The Classic Non-Dual Image", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 17.1-17.10", explanation: "You are the sky; the clouds are the mind. The sky is not affected by the clouds, not even by the storm. The Gita's most beloved image — the one to carry into difficult days.", application: "In any storm, practice the sky's stance: the clouds are real, the sky is unaffected. Not suppression — the storm is allowed; the sky is remembered.", questions: ["What storm is in my sky today?", "Can I feel the sky's unaffectedness while the storm rages?", "What is the difference between the sky's stance and denial?"], references: ["Ashtavakra Gita 17.1-17.10", "Ashtavakra Gita 9.1-9.10"], excerpt: "You are the sky; the clouds are the mind. The storm does not touch the sky.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana", "raja"], domains: ["spirituality", "health"], tags: ["ashtavakra", "sky", "clouds", "storm", "unaffected"], difficulty: "beginner", minutes: 5 },
  { concept: "The Final Chapter — Nothing Remains to Be Done", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 18.1-18.10", explanation: "The Gita closes: nothing remains to be done. The self is free, the world is appearance, the teaching is complete. The final chapter is not a summary but a release — the text itself is a raft, now to be set down.", application: "End any deep study session with the final chapter's gesture: set the teaching down. The text pointed; the pointing is complete. Rest as what was pointed to.", questions: ["What remains to be done — really?", "Can I set this teaching down as a raft?", "What is present when nothing remains to be done?"], references: ["Ashtavakra Gita 18.1-18.10", "Ashtavakra Gita 20.1-20.10"], excerpt: "Nothing remains to be done. You are free. Rest.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["ashtavakra", "final", "nothing_to_do", "release", "rest"], difficulty: "advanced", minutes: 7 },
  { concept: "The Twenty Chapters — The Gita's Complete Arc", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 1-20", explanation: "The Ashtavakra Gita's twenty chapters trace the complete arc: the witness (1-2), appearance (3-4), the mind's role (5-6), recognition (7-8), the images (9-12), the fire of knowledge (13-15), the natural state (16-17), and the release (18-20). One of the shortest and most uncompromising non-dual texts.", application: "Use the twenty-chapter arc as a study path: one chapter per session, twenty sessions. The text rewards slow reading — its brevity is density, not simplicity.", questions: ["Which chapter addresses my current question?", "What is the arc from witness to release?", "Where does the text challenge me most?"], references: ["Ashtavakra Gita 1-20", "Ashtavakra Gita commentaries"], excerpt: "Twenty chapters, one direction: from the witness to the release.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["ashtavakra", "twenty_chapters", "arc", "study_path", "non_dual"], difficulty: "advanced", minutes: 10 },
  { concept: "The Dialogue Frame — Student and Master", tradition: "Ashtavakra Gita", source: "Ashtavakra Gita 1.1", explanation: "The text is framed as a dialogue between the sage Ashtavakra and King Janaka — the student a king, the teacher a deformed child. The frame itself teaches: wisdom does not respect appearance, and authority does not confer understanding.", application: "Notice who teaches you. The frame suggests the most unlikely sources carry the clearest teachings — and the most authoritative sources may carry only appearance.", questions: ["Who are my unlikely teachers?", "Where am I respecting appearance over understanding?", "What would the Ashtavakra-Janaka frame say about my spiritual life?"], references: ["Ashtavakra Gita 1.1", "Ashtavakra Gita 1.2-1.5"], excerpt: "Janaka asked; Ashtavakra answered. The king learned from the child.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["ashtavakra", "dialogue", "janaka", "frame", "appearance"], difficulty: "beginner", minutes: 5 },
];

export const WISDOM_VIVEKACHUDAMANI: WisdomArchetype[] = [
  { concept: "The Rare Human Birth", tradition: "Vivekachudamani", source: "Vivekachudamani 13-14", explanation: "Shankara's opening argument: human birth is rare, the desire for liberation rarer still, and a teacher's contact rarest of all. The three rarities together constitute the opportunity the text addresses. The teaching begins with urgency, not comfort.", application: "Use the three rarities as a daily calibration: this birth, this desire, this contact with teaching — each is improbable. The calibration is not guilt but gravity.", questions: ["What would I do differently if this birth's rarity were felt, not believed?", "Is my desire for liberation genuine or inherited?", "What am I doing with the contact I have?"], references: ["Vivekachudamani 13-14", "Vivekachudamani 15-16"], excerpt: "Human birth is rare; the desire for liberation, rarer; the teacher's contact, rarest of all.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["spirituality", "purpose"], tags: ["vivekachudamani", "shankara", "rare_birth", "urgency", "opportunity"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Four Sadhanas — The Means of Practice", tradition: "Vivekachudamani", source: "Vivekachudamani 15-20", explanation: "Shankara's fourfold qualification: viveka (discrimination between real and unreal), vairagya (dispassion for the fruits of action), shad-sampatti (the six virtues — tranquility, restraint, withdrawal, endurance, faith, concentration), and mumukshutva (intense longing for liberation). The complete entrance requirements for the path.", application: "Use the four as a self-assessment before deep practice: which qualification is strongest, which absent? The text is honest — without all four, study remains intellectual.", questions: ["Which of the four sadhanas is strongest in me?", "Which is absent — and what would cultivate it?", "Is my longing for liberation intense enough to be called mumukshutva?"], references: ["Vivekachudamani 15-20", "Vivekachudamani 21-25"], excerpt: "Viveka, vairagya, the six virtues, and mumukshutva — the four means.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "sadhanas", "viveka", "vairagya", "shad_sampatti", "mumukshutva"], difficulty: "intermediate", minutes: 9 },
  { concept: "Viveka — Discrimination Between Real and Unreal", tradition: "Vivekachudamani", source: "Vivekachudamani 21-25", explanation: "The first sadhana defined: viveka is the discrimination between the eternal and the transient, the self and the non-self. Not a belief but a capacity — the trained ability to see what endures and what changes. The text treats it as the foundation of all foundations.", application: "Practice viveka as a daily sorting: in every experience, ask 'is this enduring or transient?' The body, roles, moods — transient. The awareness of them — enduring. The sorting is the practice.", questions: ["What in my current life am I treating as enduring that is transient?", "What transient thing am I building identity on?", "Where is my discrimination accurate but unused?"], references: ["Vivekachudamani 21-25", "Vivekachudamani 26-30"], excerpt: "Viveka is the discrimination between the eternal and the transient.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "growth"], tags: ["vivekachudamani", "viveka", "discrimination", "eternal", "transient"], difficulty: "intermediate", minutes: 7 },
  { concept: "Vairagya — Dispassion for Fruits", tradition: "Vivekachudamani", source: "Vivekachudamani 26-30", explanation: "The second sadhana: vairagya — not aversion to the world but the cessation of craving for action's fruits. Shankara is precise: vairagya is not running away; it is the dropping of the grip. The world is not rejected; the grasping is.", application: "Test vairagya in action: do the next task with full effort and zero claim on its result. The task is unchanged; the inner chemistry is not.", questions: ["What fruit am I gripping today?", "What would full effort with zero claim look like?", "Is my dispassion aversion in disguise — and how would I know?"], references: ["Vivekachudamani 26-30", "Bhagavad Gita 2.47"], excerpt: "Vairagya is the cessation of craving for the fruits of action.", evidence: "traditional", dimensions: ["emotion", "action", "thought"], paths: ["jnana", "karma"], domains: ["growth", "work"], tags: ["vivekachudamani", "vairagya", "dispassion", "fruits", "grasping"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Six Virtues — Shad-Sampatti", tradition: "Vivekachudamani", source: "Vivekachudamani 31-35", explanation: "The third sadhana's six components: shama (tranquility of mind), dama (restraint of senses), uparati (withdrawal from worldly functions), titiksha (endurance), shraddha (faith in the teaching and teacher), and samadhana (single-pointed resolve). The complete character preparation for inquiry.", application: "Use the six as a weekly character audit. Most practitioners find one or two strong and several absent — the text's point is that all six are required, like six legs of a table.", questions: ["Which of the six virtues is strongest in me?", "Which is missing — and what is its cost?", "What would one week of practicing the weakest virtue look like?"], references: ["Vivekachudamani 31-35", "Vivekachudamani 36-40"], excerpt: "Shama, dama, uparati, titiksha, shraddha, samadhana — the six virtues.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["vivekachudamani", "shad_sampatti", "six_virtues", "shama", "dama", "titiksha"], difficulty: "intermediate", minutes: 8 },
  { concept: "Mumukshutva — The Longing for Liberation", tradition: "Vivekachudamani", source: "Vivekachudamani 36-40", explanation: "The fourth sadhana: mumukshutva — intense longing for liberation, not as a distant wish but as the consuming priority that reorganizes life around it. Shankara treats it as the qualification that makes the other three effective.", application: "Ask the qualifying question honestly: is liberation a wish or a priority? The difference is measurable — priorities reorganize schedules; wishes decorate them.", questions: ["Is liberation a wish or a priority in my life?", "What would reorganizing around it change this month?", "What am I unconsciously prioritizing instead?"], references: ["Vivekachudamani 36-40", "Vivekachudamani 41-45"], excerpt: "Mumukshutva — the intense longing for liberation, the fourth means.", evidence: "traditional", dimensions: ["spirit", "thought", "action"], paths: ["jnana"], domains: ["spirituality", "purpose"], tags: ["vivekachudamani", "mumukshutva", "longing", "liberation", "priority"], difficulty: "advanced", minutes: 7 },
  { concept: "The Rope and the Snake — Shankara's Central Analogy", tradition: "Vivekachudamani", source: "Vivekachudamani 37-38", explanation: "Shankara's most famous analogy: the rope mistaken for a snake in dim light. The snake was never real — only the rope was. Similarly, the world is brahman mistaken for a world. The analogy's precision: the error is real as experience, unreal as entity.", application: "Apply the analogy to any current fear: the rope is the situation, the snake is the story. Seeing the rope does not deny the situation; it removes the snake. The relief is immediate when the analogy is applied, not merely admired.", questions: ["What snake am I seeing right now?", "What is the rope — the actual situation?", "What changes when the snake is seen as never having existed?"], references: ["Vivekachudamani 37-38", "Vivekachudamani 117-120", "Brihadaranyaka Upanishad"], excerpt: "The rope mistaken for a snake — the world is brahman mistaken for a world.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "spirituality"], tags: ["vivekachudamani", "rope", "snake", "analogy", "error"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Dream Analogy — The World as Dream", tradition: "Vivekachudamani", source: "Vivekachudamani 41-45", explanation: "Shankara's second great analogy: the world is like a dream — experienced vividly, upon waking recognized as mind-made. The dream's precision: it was real as experience, unreal as entity. The waking state is the same structure, one dream longer.", application: "Use the dream analogy as an evening practice: review the day as a dream — vivid, meaningful, and not the self. The review is not dismissal; it is the beginning of accurate seeing.", questions: ["What was today's dream containing?", "What would waking from this dream feel like — and who would wake?", "Can I hold the day as real-as-experience and unreal-as-entity simultaneously?"], references: ["Vivekachudamani 41-45", "Vivekachudamani 113-116", "Mandukya Upanishad"], excerpt: "The world is like a dream — vivid, meaningful, and not the self.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["spirituality", "growth"], tags: ["vivekachudamani", "dream", "analogy", "waking", "mind_made"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Space in the Pot — The Fifth Analogy", tradition: "Vivekachudamani", source: "Vivekachudamani 55-60", explanation: "The pot's space and the sky's space: one space, seemingly divided by the pot's walls. Break the pot — the space was never divided. Shankara's analogy for the self's relation to the body: the body is the pot; you are the space.", application: "The pot analogy is the library's most practical non-dual image: in any confinement (role, body, situation), remember the space was never confined. The walls are real; the confinement is the mistake.", questions: ["What pot am I currently mistaking for my boundary?", "Where do I feel confined that the space was never confined?", "What changes when the pot is seen as pot, not as space?"], references: ["Vivekachudamani 55-60", "Ashtavakra Gita 11", "Yoga Vasistha"], excerpt: "The space in the pot is not the pot's space — it is the sky's, seemingly divided.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["vivekachudamani", "pot", "space", "sky", "analogy"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Five Sheaths — Pancha Kosha Analysis", tradition: "Vivekachudamani", source: "Vivekachudamani 67-72", explanation: "Shankara's systematic analysis of the five sheaths — food, breath, mind, intellect, bliss — with the instruction that the self is not any of them. Each sheath is 'not this' (neti neti); the subtraction leaves the witness.", application: "Use the five sheaths as a daily subtraction: when a state claims identity ('I am tired', 'I am anxious'), locate the sheath and subtract. The subtraction is the practice; the remainder is the teaching.", questions: ["Which sheath is claiming identity today?", "What remains after subtracting it?", "Can I subtract all five — and what remains?"], references: ["Vivekachudamani 67-72", "Taittiriya Upanishad 2.1-2.7"], excerpt: "The self is not the food-sheath, not the breath-sheath, not the mind-sheath, not the intellect-sheath, not the bliss-sheath.", evidence: "traditional", dimensions: ["thought", "spirit", "body"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "five_sheaths", "pancha_kosha", "neti_neti", "subtraction"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Three Bodies — Gross, Subtle, Causal", tradition: "Vivekachudamani", source: "Vivekachudamani 78-85", explanation: "The three bodies: gross (sthula, the physical), subtle (sukshma, the mind-senses-energy), and causal (karana, the seed state of deep sleep). The self is the witness of all three — present in waking, dreaming, and deep sleep, unchanged by all.", application: "Map your three bodies: the gross you care for (health), the subtle you train (mind), the causal you barely visit (deep sleep). The witness attends all three — the teaching is to know it.", questions: ["Which body do I attend to most — and which do I neglect?", "Who witnessed my deep sleep?", "Can I feel the witness present in all three bodies?"], references: ["Vivekachudamani 78-85", "Mandukya Upanishad 3-7"], excerpt: "The three bodies — gross, subtle, causal — are objects; the witness is their subject.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "three_bodies", "gross", "subtle", "causal", "witness"], difficulty: "advanced", minutes: 9 },
  { concept: "The Mahavakyas — The Four Great Sayings", tradition: "Vivekachudamani", source: "Vivekachudamani 105-110", explanation: "Shankara's treatment of the four Mahavakyas: prajnanam brahma (consciousness is brahman), tat tvam asi (thou art that), ayam atma brahma (this self is brahman), aham brahmasmi (I am brahman). Each is a direct pointer; together they are the teaching's compressed form.", application: "Contemplate one Mahavakya per week — not as affirmation but as inquiry. 'Thou art that': what is the 'thou' that remains when every 'this' is subtracted?", questions: ["Which Mahavakya resonates most — and why?", "What is the difference between repeating a Mahavakya and inquiring into it?", "Which of the four pointers is most needed by my mind?"], references: ["Vivekachudamani 105-110", "Chandogya, Brihadaranyaka, Aitareya, Mandukya Upanishads"], excerpt: "Prajnanam brahma, tat tvam asi, ayam atma brahma, aham brahmasmi — the four great sayings.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality", "learning"], tags: ["vivekachudamani", "mahavakyas", "tat_tvam_asi", "aham_brahmasmi", "pointers"], difficulty: "advanced", minutes: 9 },
  { concept: "The Nature of Brahman — Sat-Chit-Ananda", tradition: "Vivekachudamani", source: "Vivekachudamani 113-120", explanation: "Shankara's description of brahman: existence-knowledge-bliss absolute (sat-chit-ananda). Not three attributes but three inadequate words for one reality — that which is, that which knows, that which is joy. The description's purpose is to point beyond description.", application: "Use the triple description as a contemplation sequence: rest in existence (I am), then awareness (I know), then the bliss that is not emotion but the nature of awareness itself. The sequence is the practice.", questions: ["Can I distinguish existing from knowing from being joyful?", "Is ananda an emotion or the nature of awareness?", "What is the simplest test of sat — that I am?"], references: ["Vivekachudamani 113-120", "Taittiriya Upanishad 3.6", "Brihadaranyaka Upanishad 3.9.28"], excerpt: "Sat-chit-ananda — existence, awareness, bliss. One reality, three inadequate words.", evidence: "traditional", dimensions: ["spirit"], paths: ["jnana"], domains: ["spirituality"], tags: ["vivekachudamani", "brahman", "sat_chit_ananda", "existence", "bliss"], difficulty: "advanced", minutes: 9 },
  { concept: "The World Is Mithya — Neither Real nor Unreal", tradition: "Vivekachudamani", source: "Vivekachudamani 172-180", explanation: "Shankara's most subtle teaching: the world is mithya — neither absolutely real (like brahman) nor absolutely unreal (like a hare's horn). It is experienced but not ultimately existent, like the rope's snake. Mithya is the category that dissolves the real/unreal dichotomy.", application: "Mithya is the library's most useful epistemology for daily life: the world is real enough to act in, unreal enough not to suffer for. Hold both — the snake was real as experience, unreal as entity.", questions: ["Where am I treating the world as absolutely real — and suffering for it?", "Where am I treating it as unreal — and becoming careless?", "What is the middle category of mithya, experientially?"], references: ["Vivekachudamani 172-180", "Vivekachudamani 228-231", "Brahma Sutras 2.1.14"], excerpt: "The world is mithya — neither real nor unreal, like the rope's snake.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "mithya", "neither_real_nor_unreal", "epistemology", "snake"], difficulty: "advanced", minutes: 9 },
  { concept: "The Jiva Is Brahman — The Great Identity", tradition: "Vivekachudamani", source: "Vivekachudamani 200-210", explanation: "The teaching's central identity: the individual self (jiva) is brahman. Not similar, not related, not aspiring — identical. The difference is not in the self but in the misapprehension. Shankara's formulation: the rope is the snake's only reality; brahman is the jiva's only reality.", application: "The identity is not a belief to adopt but a hypothesis to test: act as if the jiva is brahman for one week and observe what changes. The text promises the test is its own confirmation.", questions: ["What would change if the jiva-brahman identity were literally true?", "What is the difference between believing it and testing it?", "Where is the misapprehension — and what is its correction?"], references: ["Vivekachudamani 200-210", "Vivekachudamani 228-231"], excerpt: "The jiva is brahman. The difference is misapprehension, not reality.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["vivekachudamani", "jiva", "brahman", "identity", "misapprehension"], difficulty: "advanced", minutes: 8 },
  { concept: "The Means of Knowledge — Pramanas", tradition: "Vivekachudamani", source: "Vivekachudamani 228-235", explanation: "Shankara's epistemology: the means of valid knowledge (pramana) — perception, inference, testimony — and their limits. The self is not known by any pramana; it is the knower of all knowing. The teaching's most precise argument: the eye sees everything but itself; the self knows everything but is not itself known.", application: "Use the pramana analysis to end the search for proof of the self: the self is not an object of knowledge but the subject of all knowing. The search ends when the seeker is recognized as the sought.", questions: ["What am I trying to prove — and with which pramana?", "Can the eye see itself? Can the self be known as an object?", "What is the difference between knowing the self and being the self?"], references: ["Vivekachudamani 228-235", "Vivekachudamani 118-125"], excerpt: "The self is not known by any means of knowledge — it is the knower of all knowing.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "pramanas", "means_of_knowledge", "knower", "subject"], difficulty: "advanced", minutes: 9 },
  { concept: "The Jivanmukta — Liberated While Living", tradition: "Vivekachudamani", source: "Vivekachudamani 271-280", explanation: "Shankara's portrait of the jivanmukta — liberated while living: unaffected by joy and sorrow, like the sky by clouds; speaking, acting, sleeping, waking — but never identified. The text's most practical chapter: what liberation looks like in daily behavior.", application: "Use the jivanmukta portrait as the library's behavioral standard: not extraordinary experiences but ordinary behavior with extraordinary freedom. Measure progress by conduct, not by states.", questions: ["What would the jivanmukta's behavior look like in my workplace?", "Which of the portrait's features is closest to my current conduct?", "Can I measure progress by behavior rather than experience?"], references: ["Vivekachudamani 271-280", "Vivekachudamani 281-290", "Bhagavad Gita 5.13"], excerpt: "The jivanmukta speaks, acts, sleeps, wakes — but is never identified.", evidence: "traditional", dimensions: ["spirit", "action", "emotion"], paths: ["jnana"], domains: ["growth", "work"], tags: ["vivekachudamani", "jivanmukta", "liberated_living", "behavior", "conduct"], difficulty: "advanced", minutes: 9 },
  { concept: "The Sage's Behavior — The Final Test", tradition: "Vivekachudamani", source: "Vivekachudamani 286-300", explanation: "The text's closing behavioral portrait: the sage is beyond praise and blame, like the sky; the world's pairs of opposites do not disturb. The final test of the teaching is not experience but behavior — the sage's conduct is the teaching's proof.", application: "The behavioral test is available today: when praised or blamed, notice the disturbance. The sage's sky-like stance is not suppression but the absence of the claim that praise or blame touches the self.", questions: ["What disturbs me — praise or blame — and why?", "What would the sky's stance look like in my next conflict?", "Is my behavior the teaching's proof or its embarrassment?"], references: ["Vivekachudamani 286-300", "Vivekachudamani 301-310"], excerpt: "The sage is like the sky — beyond praise and blame.", evidence: "traditional", dimensions: ["emotion", "action", "spirit"], paths: ["jnana", "karma"], domains: ["growth", "relationships"], tags: ["vivekachudamani", "sage", "behavior", "sky", "praise", "blame"], difficulty: "advanced", minutes: 8 },
  { concept: "The Fruit of Knowledge — The Final Verses", tradition: "Vivekachudamani", source: "Vivekachudamani 311-330", explanation: "Shankara's closing: knowledge is the fruit of all practices, and the practices are its causes. The text ends with the teaching's completion — the self is brahman, the world is appearance, and the seeker is free. The final verses are a release, not a summary.", application: "End any study of the Vivekachudamani with its own gesture: the teaching is complete, the seeker is free, the text is a raft now to be set down. The practice is the setting down.", questions: ["What is the teaching's completion — and am I trying to extend it?", "What would setting this text down look like?", "What is free, right now, that the seeking obscures?"], references: ["Vivekachudamani 311-330", "Vivekachudamani 1-12"], excerpt: "The self is brahman; the world is appearance; the seeker is free. The teaching is complete.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["vivekachudamani", "completion", "fruit", "knowledge", "release"], difficulty: "advanced", minutes: 8 },
  { concept: "The Teacher's Grace — The Opening Invocation", tradition: "Vivekachudamani", source: "Vivekachudamani 1-12", explanation: "The text opens with Shankara's salutation to Govinda and the request for the teacher's grace — the tradition's acknowledgment that the teaching's transmission requires more than text. The invocation is not ritual decoration but epistemology: the teacher's grace is the means by which the words become seeing.", application: "The invocation's lesson for self-study: approach every teaching with the posture of reception, not consumption. The text is a mirror; the grace is the light. Both are needed.", questions: ["What is my posture toward teaching — reception or consumption?", "Who or what is my Govinda — my object of salutation?", "What would 'the teacher's grace' mean in a self-directed practice life?"], references: ["Vivekachudamani 1-12", "Vivekachudamani 26-30"], excerpt: "Salutation to Govinda. Grant me the teacher's grace.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["jnana", "bhakti"], domains: ["spirituality", "learning"], tags: ["vivekachudamani", "invocation", "teacher", "grace", "reception"], difficulty: "beginner", minutes: 5 },
  { concept: "The Body Is Not the Self — The First Discrimination", tradition: "Vivekachudamani", source: "Vivekachudamani 46-55", explanation: "The first discrimination the text performs: the body is not the self. The body is seen by the self; the seen cannot be the seer. The argument is simple, relentless, and the foundation of all that follows.", application: "Apply the first discrimination literally: the body is seen (in mirror, in sensation, in aging); the seer is not seen. The practice is not to disown the body but to stop mistaking it for the self.", questions: ["Where do I treat the seen as the seer?", "What is the body's evidence that it is an object?", "What is the difference between disowning the body and not being it?"], references: ["Vivekachudamani 46-55", "Vivekachudamani 56-66"], excerpt: "The body is seen; the seer is not seen. The seen cannot be the seer.", evidence: "traditional", dimensions: ["body", "spirit", "thought"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "body", "not_self", "seer", "seen", "first_discrimination"], difficulty: "beginner", minutes: 6 },
  { concept: "The Mind Is Not the Self — The Second Discrimination", tradition: "Vivekachudamani", source: "Vivekachudamani 56-66", explanation: "The second discrimination: the mind is not the self. The mind is an instrument — thinking, feeling, deciding — but it is known by the self. The instrument cannot be the player. The text's argument extends the first discrimination inward.", application: "The second discrimination is the library's most practical: every thought, mood, and decision is an object in awareness. The practice is to stop claiming the mind's contents as the self — the contents are the mind's, not yours.", questions: ["Which mind-content am I currently claiming as 'me'?", "What is the evidence that the mind is an instrument?", "What remains when the mind's contents are all set down?"], references: ["Vivekachudamani 56-66", "Vivekachudamani 67-72"], excerpt: "The mind is an instrument, known by the self. The instrument is not the player.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "growth"], tags: ["vivekachudamani", "mind", "not_self", "instrument", "second_discrimination"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Intellect Is Not the Self — The Third Discrimination", tradition: "Vivekachudamani", source: "Vivekachudamani 67-72", explanation: "The third discrimination: the intellect (buddhi) — the discriminating, deciding function — is not the self. The most subtle misidentification: the one who discriminates is mistaken for the discrimination. The text's argument: the intellect's decisions are known; the knower is not decided.", application: "The third discrimination catches the spiritual ego: the one who practices discrimination is not the discrimination. The practice is to notice the deciding function as an object — and the decider as the self.", questions: ["Where is my spiritual ego — the decider claiming to be the decision?", "What is the evidence that the intellect is an instrument?", "Who decides — and can the decider be decided?"], references: ["Vivekachudamani 67-72", "Vivekachudamani 73-77"], excerpt: "The intellect decides; the self knows the deciding. The decider is not the decision.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["learning", "spirituality"], tags: ["vivekachudamani", "intellect", "buddhi", "not_self", "third_discrimination"], difficulty: "advanced", minutes: 7 },
  { concept: "The Bliss Sheath Is Not the Self — The Fourth Discrimination", tradition: "Vivekachudamani", source: "Vivekachudamani 73-77", explanation: "The fourth and subtlest discrimination: even the bliss sheath (anandamaya) — the deepest layer of joy — is not the self. The bliss is experienced; the experiencer is not experienced. The text's warning: the most subtle misidentification is the last to fall.", application: "The fourth discrimination is the advanced practitioner's checkpoint: are spiritual experiences being claimed as the self? The bliss is the sheath; the self is the witness of the bliss. The distinction is the teaching.", questions: ["Am I claiming spiritual experiences as the self?", "What is the difference between experiencing bliss and being the witness of bliss?", "What remains when even the bliss sheath is set down?"], references: ["Vivekachudamani 73-77", "Vivekachudamani 78-85"], excerpt: "The bliss is experienced; the experiencer is not experienced. The witness is not the witnessed.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["jnana"], domains: ["spirituality"], tags: ["vivekachudamani", "bliss", "anandamaya", "not_self", "fourth_discrimination"], difficulty: "advanced", minutes: 8 },
];

export const WISDOM_DHAMMAPADA: WisdomArchetype[] = [
  { concept: "Mind Precedes All States", tradition: "Dhammapada", source: "Dhammapada 1.1-1.2", explanation: "The Dhammapada's opening: mind precedes all mental states; mind is their chief; they are all mind-wrought. If one speaks or acts with impure mind, suffering follows like the wheel that follows the ox's foot. If with pure mind, happiness follows like a never-departing shadow.", application: "Use the opening as a daily diagnostic: before any action, check the mind's state — impure or pure. The wheel follows the foot; the shadow follows the person. The state is the cause; the day is the result.", questions: ["What state is my mind in right now — impure or pure?", "What is today's wheel following?", "What would one degree of purity change in the next hour?"], references: ["Dhammapada 1.1-1.2", "Dhammapada 1.3-1.5"], excerpt: "Manopubbangamā dhammā, manoseṭṭhā manomayā — Mind precedes all states; mind is their chief.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["growth", "learning"], tags: ["dhammapada", "mind", "precedes", "chief", "wheel", "shadow"], difficulty: "beginner", minutes: 5 },
  { concept: "Hatred Never Ceases by Hatred", tradition: "Dhammapada", source: "Dhammapada 1.5-1.6", explanation: "The Buddha's most quoted law: hatred never ceases by hatred in this world; by non-hatred alone does it cease. This is a law eternal. The text presents it not as idealism but as mechanics — hatred feeding hatred is the machine; non-hatred is its only brake.", application: "Apply the law to one current conflict: where is hatred being answered with hatred? The brake is not weakness but the only mechanism that works. The law is descriptive, not prescriptive — it describes what actually happens.", questions: ["Where am I answering hatred with hatred today?", "What would non-hatred look like — not as feeling but as action?", "Can I distinguish non-hatred from appeasement?"], references: ["Dhammapada 1.5-1.6", "Dhammapada 17.1-17.3"], excerpt: "Na hi verena verāni — Hatred never ceases by hatred; by non-hatred alone it ceases.", evidence: "traditional", dimensions: ["emotion", "connection"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["dhammapada", "hatred", "non_hatred", "eternal_law", "brake"], difficulty: "beginner", minutes: 5 },
  { concept: "Heedfulness Is the Path to the Deathless", tradition: "Dhammapada", source: "Dhammapada 2.1-2.2", explanation: "Appamada — heedfulness, diligence — is the path to the deathless; heedlessness is the path of death. The heedful do not die; the heedless are as if already dead. The Dhammapada's second chapter makes diligence the foundation of everything else.", application: "The teaching is a work ethic for the spirit: the path is maintained by attention, not by inspiration. Schedule heedfulness — small, daily, unbroken — and let inspiration be its occasional visitor.", questions: ["Where is my heedlessness strongest — and what is its cost?", "What would one act of appamada look like today?", "Is my practice maintained by attention or by inspiration?"], references: ["Dhammapada 2.1-2.2", "Dhammapada 2.3-2.6"], excerpt: "Appamādo amatapadaṃ, pamādo macchuno padaṃ — Heedfulness is the path to the deathless.", evidence: "traditional", dimensions: ["thought", "action"], paths: ["raja", "karma"], domains: ["growth", "discipline"], tags: ["dhammapada", "heedfulness", "appamada", "diligence", "deathless"], difficulty: "beginner", minutes: 5 },
  { concept: "The Mind Is Hard to Hold", tradition: "Dhammapada", source: "Dhammapada 3.1-3.5", explanation: "The mind is fickle, unsteady, difficult to restrain — like a fish taken from water and thrown on land, it flaps anywhere. The third chapter's honesty about the mind's nature is the foundation for patience with practice: the difficulty is not your failure; it is the mind's nature.", application: "When practice feels like failure because the mind wanders, recall the fish: of course it flaps. The practice is not to stop the flapping but to return to the water — repeatedly, patiently, without drama.", questions: ["Where am I treating the mind's nature as my personal failure?", "What is my 'water' — the practice I return to?", "How many returns did I make today — and did I count them as failure or as practice?"], references: ["Dhammapada 3.1-3.5", "Dhammapada 3.6-3.10"], excerpt: "The mind is fickle, unsteady, difficult to restrain — like a fish thrown on land.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["dhammapada", "mind", "fickle", "fish", "restraint", "patience"], difficulty: "beginner", minutes: 5 },
  { concept: "The Fool and the Wise — Two Kinds of Companion", tradition: "Dhammapada", source: "Dhammapada 5.1-5.10", explanation: "The Dhammapada's fifth chapter: the fool is tormented by his own mind, as the bamboo is by its own leaves. The wise one, like the ocean, is unmoved. The text's social teaching: choose companions by their effect on your mind, not their charm.", application: "Audit your inner companions: which voices in your head are foolish (tormenting) and which are wise (oceanic)? The same audit applies to outer companions — the text is blunt about their effects.", questions: ["Which inner voices are bamboo leaves — tormenting by their own motion?", "Which are oceanic — unmoved?", "What is one companion (inner or outer) to spend less time with this week?"], references: ["Dhammapada 5.1-5.10", "Dhammapada 6.1-6.5"], excerpt: "The fool is tormented by his own mind, as the bamboo by its own leaves.", evidence: "traditional", dimensions: ["thought", "emotion", "connection"], paths: ["raja"], domains: ["growth", "relationships"], tags: ["dhammapada", "fool", "wise", "companion", "bamboo", "ocean"], difficulty: "beginner", minutes: 6 },
  { concept: "The Wise One Like the Ocean", tradition: "Dhammapada", source: "Dhammapada 6.1-6.5", explanation: "The wise one is like the great ocean — unmoved by the rivers of praise and blame, desire and aversion. The Dhammapada's image of equanimity: not the absence of inflows but the capacity to receive them without being changed.", application: "Practice the ocean's stance in one interaction today: receive the inflow (praise or blame) without being changed by it. The ocean does not refuse the river; it absorbs it.", questions: ["What is today's inflow — praise or blame?", "Can I receive it without being changed?", "What is the difference between the ocean's absorption and the stone's resistance?"], references: ["Dhammapada 6.1-6.5", "Dhammapada 6.6-6.10"], excerpt: "The wise one is like the great ocean, unmoved by the rivers of praise and blame.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["raja"], domains: ["growth", "relationships"], tags: ["dhammapada", "ocean", "equanimity", "praise", "blame", "unmoved"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Flower That Does Not Fall", tradition: "Dhammapada", source: "Dhammapada 4.1-4.10", explanation: "The fourth chapter's image: the wise one, like a flower on a mountain peak, is not touched by the world's dust. The teaching is not isolation — the flower is on the peak, in the wind — but non-adherence. The dust falls; the flower is not stained.", application: "In the world's dust — news, conflict, others' chaos — practice the flower's stance: present, in the wind, unstained. The peak is not a place but a relationship to the dust.", questions: ["Where is today's dust — and am I stained or merely touched?", "What would the flower's stance look like in my next difficult interaction?", "Is my non-adherence wisdom or avoidance?"], references: ["Dhammapada 4.1-4.10", "Dhammapada 4.11-4.15"], excerpt: "Like a flower on a mountain peak, the wise one is not touched by the world's dust.", evidence: "traditional", dimensions: ["emotion", "spirit", "connection"], paths: ["raja", "jnana"], domains: ["growth", "work"], tags: ["dhammapada", "flower", "dust", "peak", "non_adherence"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Thousand Words and the One Word of Meaning", tradition: "Dhammapada", source: "Dhammapada 3.1-3.3", explanation: "Though a thousand meaningless words are spoken, one word of meaning is better — hearing which, one is pacified. The Dhammapada's teaching on speech's economy: quantity is noise; meaning is peace.", application: "Apply the teaching to information consumption: one meaningful sentence, heard and digested, pacifies more than a thousand headlines. The practice is the curation of intake.", questions: ["What is my 'one word of meaning' today?", "How many meaningless words did I consume this morning?", "What would pacification look like — and where is it available?"], references: ["Dhammapada 3.1-3.3", "Dhammapada 3.4-3.8"], excerpt: "One word of meaning is better than a thousand meaningless words.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja", "jnana"], domains: ["learning", "work"], tags: ["dhammapada", "thousand_words", "one_word", "meaning", "pacification"], difficulty: "beginner", minutes: 5 },
  { concept: "The Abuser and the Abused — The First to Forgive", tradition: "Dhammapada", source: "Dhammapada 15.1-15.2", explanation: "Whoever abuses the peaceful one — the Dhammapada's teaching on abuse: the abuser harms himself first. The one who is abused without abusing back wins the battle that no one else can win. The text's radical non-retaliation teaching.", application: "The teaching is a strategy, not a sentiment: non-retaliation is not defeat but the only position from which the abuser's mechanism fails. Practice the first forgiveness — not for them, for the mechanism's failure.", questions: ["Where am I in an abuse dynamic — as abuser, abused, or witness?", "What would the first forgiveness look like — and who would it defeat?", "Can I distinguish non-retaliation from permission?"], references: ["Dhammapada 15.1-15.2", "Dhammapada 15.3-15.5"], excerpt: "Whoever abuses the peaceful one harms himself first. The abused who does not abuse back wins the unwinnable battle.", evidence: "traditional", dimensions: ["emotion", "connection", "action"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["dhammapada", "abuse", "forgiveness", "non_retaliation", "battle"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Tathagata — The One Thus Gone", tradition: "Dhammapada", source: "Dhammapada 26.1-26.2", explanation: "The final chapter: the Tathagata — the one thus gone — has no attachment anywhere; no longing for any home. The Dhammapada's closing portrait of the awakened one: not a place, not a state, but a manner of going — thus, without clinging.", application: "The closing teaching is a manner, not a destination: to go thus — through the day, through the conflict, through the loss — without clinging. The practice is the manner of going, not the arrival.", questions: ["What is my manner of going — clinging or thus?", "Where is my longing for a home — a place, a state, a person to complete me?", "What would 'going thus' look like in the next hour?"], references: ["Dhammapada 26.1-26.2", "Dhammapada 26.3-26.5"], excerpt: "The Tathagata — the one thus gone — has no attachment anywhere.", evidence: "traditional", dimensions: ["spirit", "action"], paths: ["raja", "jnana"], domains: ["spirituality", "growth"], tags: ["dhammapada", "tathagata", "thus_gone", "no_attachment", "manner"], difficulty: "advanced", minutes: 7 },
  { concept: "The Four Noble Truths", tradition: "Buddhism", source: "Dhammapada; Samyutta Nikaya", explanation: "The Buddha's foundational teaching: the truth of suffering (dukkha), the truth of suffering's origin (craving), the truth of suffering's cessation (nibbana), and the truth of the path leading to cessation (the eightfold path). The Dhammapada assumes them; they are the frame of every verse.", application: "Use the four truths as a diagnostic, not a doctrine: where is suffering, what is its craving, is cessation conceivable, what is the next step of the path? The truths are medical — diagnosis, cause, prognosis, treatment.", questions: ["What is today's dukkha — and what is its craving?", "Is cessation conceivable in this case?", "What is the next step of the path — not the whole path, the next step?"], references: ["Dhammapada (throughout)", "Samyutta Nikaya 56.11", "The Middle Length Discourses"], excerpt: "Suffering, its origin, its cessation, and the path — the four noble truths.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["raja", "jnana"], domains: ["learning", "growth"], tags: ["dhammapada", "buddhism", "four_noble_truths", "dukkha", "craving", "path"], difficulty: "beginner", minutes: 8 },
  { concept: "The Eightfold Path", tradition: "Buddhism", source: "Dhammapada 20; Magga Vagga", explanation: "The path's eight factors: right view, right intention, right speech, right action, right livelihood, right effort, right mindfulness, right concentration. The Dhammapada's twentieth chapter presents the path as the only way to the deathless — not one way among many.", application: "Use the eight factors as a life audit: which factor is strongest, which weakest? The path is not sequential but simultaneous — all eight are practiced together, each supporting the others.", questions: ["Which of the eight factors is strongest in my life?", "Which is weakest — and what is its cost?", "What is one act of right speech, right action, or right livelihood available today?"], references: ["Dhammapada 20.1-20.5", "Samyutta Nikaya 45.8", "The Middle Length Discourses"], excerpt: "Right view, intention, speech, action, livelihood, effort, mindfulness, concentration — the eightfold path.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["raja", "karma"], domains: ["learning", "growth", "work"], tags: ["dhammapada", "eightfold_path", "right", "factors", "audit"], difficulty: "beginner", minutes: 8 },
  { concept: "The Five Aggregates — What You Are Not", tradition: "Buddhism", source: "Dhammapada; Anatta-lakkhana Sutta", explanation: "The teaching of anatta: form, feeling, perception, mental formations, consciousness — the five aggregates — are not the self. Each is impermanent; what is impermanent is suffering; what is suffering is not self. The Dhammapada's verses on non-self are the library's most radical.", application: "Practice the aggregate subtraction: when a state claims identity ('I am angry'), locate the aggregate (feeling, mental formation) and subtract. The subtraction is not denial — the anger is real as aggregate, unreal as self.", questions: ["Which aggregate is claiming identity right now?", "What is impermanent about it — and what is the suffering in mistaking it for self?", "What remains after the subtraction?"], references: ["Dhammapada 1.1-1.5", "Anatta-lakkhana Sutta", "Samyutta Nikaya 22"], excerpt: "Form is not self, feeling is not self, perception is not self, formations are not self, consciousness is not self.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana", "raja"], domains: ["learning", "spirituality"], tags: ["dhammapada", "five_aggregates", "anatta", "non_self", "subtraction"], difficulty: "advanced", minutes: 9 },
  { concept: "The Three Marks — Impermanence, Suffering, Non-Self", tradition: "Buddhism", source: "Dhammapada 1.1-1.5; 20.1", explanation: "The three characteristics of all conditioned things: anicca (impermanence), dukkha (unsatisfactoriness), anatta (non-self). The Dhammapada's verses return to these three marks as the lens for every experience — the teaching's operating system.", application: "Apply the three marks to one current attachment: is it permanent? is it satisfiable? is it self? The marks are not pessimism — they are the release mechanism: what is impermanent need not be gripped.", questions: ["What am I gripping today — and what are its three marks?", "Where is impermanence most visible and least accepted?", "What would releasing the grip look like — not as loss but as accuracy?"], references: ["Dhammapada 1.1-1.5", "Dhammapada 20.1", "Anatta-lakkhana Sutta"], excerpt: "Impermanent, unsatisfactory, non-self — the three marks of all conditioned things.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["jnana", "raja"], domains: ["learning", "growth"], tags: ["dhammapada", "three_marks", "anicca", "dukkha", "anatta", "impermanence"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Middle Way", tradition: "Buddhism", source: "Dhammapada 1.1-1.2; Dhammacakkappavattana Sutta", explanation: "The Buddha's first teaching: the middle way between the extremes of indulgence and mortification. The Dhammapada's verses on moderation are the same teaching in daily form — the middle way is not a compromise but the discovery that both extremes are the same error in different costumes.", application: "Find today's extremes: where is indulgence (overconsumption of input, food, stimulation) and where is mortification (self-punishment, deprivation)? The middle way is the third option — neither, but not lukewarm: precise.", questions: ["What are today's two extremes?", "Where is my 'middle' — not compromise but precision?", "What would the middle way look like in this specific domain?"], references: ["Dhammapada 1.1-1.2", "Dhammacakkappavattana Sutta", "Dhammapada 1.6-1.8"], excerpt: "The middle way — between indulgence and mortification, the path of precision.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["raja", "karma"], domains: ["growth", "health"], tags: ["dhammapada", "middle_way", "extremes", "indulgence", "mortification", "precision"], difficulty: "beginner", minutes: 6 },
  { concept: "The Four Immeasurables", tradition: "Buddhism", source: "Dhammapada; Karaniya Metta Sutta", explanation: "The four brahmaviharas — loving-kindness (metta), compassion (karuna), sympathetic joy (mudita), equanimity (upekkha) — the Dhammapada's verses on goodwill are their popular form. The four are immeasurable: their scope is not limited by the object's worthiness.", application: "Practice the four as a sequence: metta for the loved one, karuna for the suffering one, mudita for the successful one, upekkha for the difficult one. The sequence is the practice; the immeasurability is the result.", questions: ["Which of the four is strongest in me — and which is absent?", "Who is the difficult one — and can upekkha hold them?", "What is the difference between equanimity and indifference?"], references: ["Dhammapada 5.1-5.5", "Karaniya Metta Sutta", "Visuddhimagga"], excerpt: "Loving-kindness, compassion, sympathetic joy, equanimity — the four immeasurables.", evidence: "traditional", dimensions: ["emotion", "connection", "spirit"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["dhammapada", "four_immeasurables", "metta", "karuna", "mudita", "upekkha"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Five Precepts — The Training Rules", tradition: "Buddhism", source: "Dhammapada 10.1-10.5", explanation: "The Dhammapada's tenth chapter on non-violence is the first precept's expansion: not killing, not stealing, not lying, not misusing sexuality, not intoxicating — the five training rules. The text treats them not as commandments but as training — the grammar of a life that does not harm.", application: "Use the five as a weekly grammar check: which precept is most strained? The precepts are not moral decoration but the foundation of concentration — a mind at war with its own conduct cannot settle.", questions: ["Which precept is most strained in my life?", "What is the cost of that strain to my concentration?", "What is one act of training — not perfection — available today?"], references: ["Dhammapada 10.1-10.5", "Dhammapada 10.6-10.10", "The Middle Length Discourses"], excerpt: "Not killing, not stealing, not lying, not misusing sexuality, not intoxicating — the five training rules.", evidence: "traditional", dimensions: ["action", "thought", "emotion"], paths: ["karma", "raja"], domains: ["growth", "ethics"], tags: ["dhammapada", "five_precepts", "training", "non_violence", "grammar"], difficulty: "beginner", minutes: 7 },
  { concept: "The Chapter of the Mind — Cittavagga", tradition: "Buddhism", source: "Dhammapada 3", explanation: "The Dhammapada's third chapter: the mind is difficult to hold, fickle, flying wherever it lists. The teaching: the mind is not the enemy — it is the instrument. Taming it is like taming the fish: not by force but by returning it to water.", application: "The chapter's lesson for modern practice: the mind's wandering is not the obstacle to meditation but its subject matter. Every return is the taming. Count returns, not failures.", questions: ["How many returns did I make today?", "Am I counting them as failures or as the practice itself?", "What is my 'water' — the place the mind returns to?"], references: ["Dhammapada 3.1-3.10", "Dhammapada 3.11-3.15"], excerpt: "The mind is fickle, difficult to hold — taming it is the practice, not the problem.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["raja"], domains: ["learning", "growth"], tags: ["dhammapada", "cittavagga", "mind", "fickle", "taming", "returns"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Flowers — Pupphavagga", tradition: "Buddhism", source: "Dhammapada 4", explanation: "The fourth chapter: who conquers the world, who is like a flower on a peak, who is undisturbed like the ocean. The Dhammapada's most beautiful chapter — its images are the teaching: the flower unstained, the ocean unmoved, the peak unshaken.", application: "Choose one image as this week's emblem: the flower (unstained), the ocean (unmoved), or the peak (unshaken). Carry the image into the day's difficulty — the image is the practice's portable form.", questions: ["Which image speaks to my current difficulty — flower, ocean, or peak?", "What would the image's stance look like today?", "Can I carry one image into the next difficult interaction?"], references: ["Dhammapada 4.1-4.10", "Dhammapada 4.11-4.15"], excerpt: "Like a flower on a peak, unstained; like the ocean, unmoved; like the peak, unshaken.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["raja"], domains: ["growth", "spirituality"], tags: ["dhammapada", "pupphavagga", "flowers", "peak", "ocean", "unstained"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Evil — Papavagga", tradition: "Buddhism", source: "Dhammapada 9", explanation: "The ninth chapter: do not do evil, do not accumulate it. The Dhammapada's blunt teaching: evil is not a single act but an accumulation — small repetitions that become character. The chapter's mercy: the accumulation works in both directions.", application: "Use the accumulation lens on one habit: is this small repetition accumulating toward or away? The chapter's teaching is behavioral, not metaphysical — the small act's weight is its repetition.", questions: ["What small repetition is accumulating in my life?", "Is it accumulating toward or away?", "What is the smallest interruption of the pattern available today?"], references: ["Dhammapada 9.1-9.5", "Dhammapada 9.6-9.10"], excerpt: "Do not do evil, do not accumulate it. Evil accumulates; so does good.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["karma", "raja"], domains: ["growth", "ethics"], tags: ["dhammapada", "papavagga", "evil", "accumulation", "repetition", "character"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Punishment — Dandavagga", tradition: "Buddhism", source: "Dhammapada 10", explanation: "The tenth chapter: everyone fears punishment, everyone loves life — therefore do not harm others. The Dhammapada's golden-rule chapter: the teaching is not abstract compassion but the simple equation of shared fear and shared love of life.", application: "The chapter's method: in any conflict, apply the equation — the other's fear of punishment and love of life equal yours. The equation is not sentiment; it is the accurate perception that dissolves the other's objectification.", questions: ["Whom am I objectifying today — and what is their fear of punishment?", "What is their love of life — and how does it equal mine?", "What changes when the equation is applied, not merely believed?"], references: ["Dhammapada 10.1-10.5", "Dhammapada 10.6-10.10"], excerpt: "Everyone fears punishment, everyone loves life. Therefore, do not harm others.", evidence: "traditional", dimensions: ["connection", "emotion", "thought"], paths: ["bhakti", "raja"], domains: ["relationships", "ethics"], tags: ["dhammapada", "dandavagga", "punishment", "golden_rule", "shared_fear"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Old Age — Jaravagga", tradition: "Buddhism", source: "Dhammapada 11", explanation: "The eleventh chapter: aging is not a future event but a present process. The Dhammapada's verses on old age are not morbid but precise — the teaching is to look at aging now, in the mirror, in the body, before it looks at you.", application: "The chapter's practice: one daily glance at aging as process — in the hands, the face, the breath. Not to fear it but to stop being surprised by it. The surprised mind suffers more than the aging body.", questions: ["Where is aging a present process in my body, right now?", "What would looking at it — not away from it — change?", "What is the difference between seeing aging and fearing it?"], references: ["Dhammapada 11.1-11.5", "Dhammapada 11.6-11.10"], excerpt: "Aging is not a future event. It is a present process — look at it now.", evidence: "traditional", dimensions: ["body", "thought", "emotion"], paths: ["raja", "jnana"], domains: ["health", "growth"], tags: ["dhammapada", "jaravagga", "old_age", "process", "mortality", "mirror"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Chapter of Self — Attavagga", tradition: "Buddhism", source: "Dhammapada 12", explanation: "The twelfth chapter: the self is its own refuge — who else could be? The Dhammapada's teaching on self-reliance is not isolation but the recognition that the practice's agent and beneficiary are the same being. The self is both the instrument and the task.", application: "The chapter's lesson for modern practitioners: stop outsourcing the practice — to apps, teachers, retreats, or future selves. The self is the refuge; the practice is the self's work on itself.", questions: ["Whom am I outsourcing my practice to?", "What would 'the self as its own refuge' look like this week?", "How is the self both the instrument and the task?"], references: ["Dhammapada 12.1-12.5", "Dhammapada 12.6-12.10", "Bhagavad Gita 6.5"], excerpt: "The self is its own refuge — who else could be? The self is both instrument and task.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["raja", "jnana"], domains: ["growth", "self_care"], tags: ["dhammapada", "attavagga", "self", "refuge", "self_reliance", "instrument"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Chapter of the World — Lokavagga", tradition: "Buddhism", source: "Dhammapada 13", explanation: "The thirteenth chapter: the world is on fire — with passion, hatred, delusion. The Dhammapada's diagnosis of the collective condition: not pessimism but triage. The fire is real; the question is whether one adds fuel or water.", application: "Apply the chapter's triage to your information diet: which inputs add fuel, which add water? The world is on fire; your attention is either kindling or extinguisher. The choice is daily and measurable.", questions: ["Which of my inputs add fuel to the fire?", "Which add water?", "What is one input to remove and one to add this week?"], references: ["Dhammapada 13.1-13.5", "Dhammapada 13.6-13.10"], excerpt: "The world is on fire — with passion, hatred, delusion. Add water, not fuel.", evidence: "traditional", dimensions: ["thought", "emotion", "connection"], paths: ["raja", "jnana"], domains: ["growth", "work"], tags: ["dhammapada", "lokavagga", "world", "fire", "fuel", "water", "triage"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Chapter of the Buddha — Buddhavagga", tradition: "Buddhism", source: "Dhammapada 14", explanation: "The fourteenth chapter: the Buddha's qualities — not as worship but as description. The awakened one is described in the Dhammapada's verses as one who has crossed over, who is unshaken, who is like the ocean. The chapter is the teaching's portrait of its own destination.", application: "Use the portrait as a direction, not a comparison: the Buddha's qualities are the path's destination described in advance. The practice is not to imitate the portrait but to walk toward its address.", questions: ["Which quality in the portrait is most needed in my life?", "What is the address — the direction — not the imitation?", "Can I hold the portrait as destination without using it as self-judgment?"], references: ["Dhammapada 14.1-14.5", "Dhammapada 14.6-14.10"], excerpt: "The awakened one has crossed over, is unshaken, is like the ocean.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["raja", "bhakti"], domains: ["spirituality", "learning"], tags: ["dhammapada", "buddhavagga", "buddha", "portrait", "destination", "crossed_over"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Chapter of Happiness — Sukhavagga", tradition: "Buddhism", source: "Dhammapada 15", explanation: "The fifteenth chapter: happiness — not as feeling but as condition. The Dhammapada's happiness teaching is structural: the happy one is free of enmity, free of illness of mind, free of the world's debt. Happiness is the byproduct of conditions, not the target of pursuit.", application: "The chapter's method: stop pursuing happiness; build its conditions. The conditions are named — freedom from enmity, mental health, independence. Audit the conditions; the byproduct follows.", questions: ["Which condition of happiness is weakest in my life — enmity, mental health, or independence?", "What is one condition-building act available today?", "Where am I pursuing happiness directly — and what is the pursuit's cost?"], references: ["Dhammapada 15.1-15.5", "Dhammapada 15.6-15.10"], excerpt: "Happiness is the byproduct of conditions — freedom from enmity, mental health, independence.", evidence: "traditional", dimensions: ["emotion", "thought", "connection"], paths: ["raja", "bhakti"], domains: ["growth", "health"], tags: ["dhammapada", "sukhavagga", "happiness", "conditions", "byproduct", "enmity"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Affection — Piyavagga", tradition: "Buddhism", source: "Dhammapada 16", explanation: "The sixteenth chapter: affection, love, the heart's movement toward. The Dhammapada's teaching: affection is not weakness but the heart's natural function — the problem is not affection but its objects and its clinging. The chapter distinguishes love from attachment with precision.", application: "Apply the distinction to one relationship: where is affection (the heart's movement) and where is attachment (the grip)? The same feeling, two structures. The practice is to keep the movement and release the grip.", questions: ["In my key relationship, where is affection and where is attachment?", "What would keeping the movement and releasing the grip look like?", "Can I love without gripping — and what is the fear in that?"], references: ["Dhammapada 16.1-16.5", "Dhammapada 16.6-16.10"], excerpt: "Affection is the heart's movement; attachment is its grip. Keep the movement, release the grip.", evidence: "traditional", dimensions: ["emotion", "connection"], paths: ["bhakti", "raja"], domains: ["relationships", "growth"], tags: ["dhammapada", "piyavagga", "affection", "love", "attachment", "grip"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Chapter of Anger — Kodhavagga", tradition: "Buddhism", source: "Dhammapada 17", explanation: "The seventeenth chapter: anger — its arising, its effects, its cessation. The Dhammapada's anger teaching is practical: the angry one harms themselves first; the one who conquers anger is praised by the wise. The chapter's method: catch anger early, at the first sensation, before the story.", application: "Use the chapter's early-warning system: anger's first signal is bodily (heat, tension, quickening). Catch it there — the story has not yet assembled. The body's signal is the intervention window.", questions: ["What is anger's first bodily signal in me?", "Where is my intervention window — before the story assembles?", "What is one act of conquering anger available today — not suppression, conquest?"], references: ["Dhammapada 17.1-17.5", "Dhammapada 17.6-17.10"], excerpt: "The angry one harms themselves first. Conquer anger at its first bodily signal.", evidence: "traditional", dimensions: ["emotion", "body", "thought"], paths: ["raja"], domains: ["health", "relationships"], tags: ["dhammapada", "kodhavagga", "anger", "early_warning", "bodily_signal", "conquest"], difficulty: "beginner", minutes: 6 },
  { concept: "The Chapter of Impurity — Malavagga", tradition: "Buddhism", source: "Dhammapada 18", explanation: "The eighteenth chapter: impurity (mala) — the rust of the mind. The Dhammapada's image: as rust on iron, so the mind's own defilements corrode it. The teaching's precision: the rust is not external; the mind corrodes itself. The remover is the same practice that removes the rope's snake — seeing.", application: "Identify today's rust: which defilement is corroding — craving, aversion, or delusion? The remover is not effort but seeing. The rust, seen, loses its invisibility — its power.", questions: ["What is today's rust — craving, aversion, or delusion?", "Where is it corroding most visibly?", "What would seeing it — not fighting it — change?"], references: ["Dhammapada 18.1-18.5", "Dhammapada 18.6-18.10"], excerpt: "As rust on iron, so the mind's defilements corrode the mind. The remover is seeing.", evidence: "traditional", dimensions: ["thought", "emotion", "spirit"], paths: ["jnana", "raja"], domains: ["growth", "learning"], tags: ["dhammapada", "malavagga", "impurity", "rust", "corrosion", "seeing"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Chapter of Righteousness — Dhammatavagga", tradition: "Buddhism", source: "Dhammapada 19", explanation: "The nineteenth chapter: righteousness (dhamma) — not as rule-following but as the law's internalization. The Dhammapada's teaching: the one who sees the law in all things is righteous; the one who merely quotes it is not. The chapter distinguishes the law's letter from its living.", application: "The chapter's test for any teaching, including this library's: is the law lived or quoted? The letter is a raft; the living is the crossing. Measure understanding by conduct, not by citation.", questions: ["Where am I quoting the law instead of living it?", "What is the difference between the letter and the living?", "What would one act of lived righteousness look like today?"], references: ["Dhammapada 19.1-19.5", "Dhammapada 19.6-19.10"], excerpt: "The one who sees the law in all things is righteous; the one who merely quotes it is not.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["jnana", "karma"], domains: ["ethics", "growth"], tags: ["dhammapada", "dhammatavagga", "righteousness", "dhamma", "letter", "living"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Chapter of the Path — Maggavagga", tradition: "Buddhism", source: "Dhammapada 20", explanation: "The twentieth chapter: the path — the Dhammapada's own summary. The path is walked step by step; the wise one walks it, the fool talks about it. The chapter's closing image: the path is not in the sky, not in the scriptures — it is in the walking.", application: "The chapter's final instruction for this library: close the book, walk the path. The path is not in the entries but in the next step — the next breath, the next return, the next act of heedfulness.", questions: ["What is my next step — not my next goal, my next step?", "Where am I talking about the path instead of walking it?", "What is the path's address in my life today — not its theory?"], references: ["Dhammapada 20.1-20.5", "Dhammapada 20.6-20.10"], excerpt: "The path is not in the sky, not in the scriptures — it is in the walking.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["raja", "karma"], domains: ["growth", "spirituality"], tags: ["dhammapada", "maggavagga", "path", "walking", "step", "not_in_sky"], difficulty: "beginner", minutes: 6 },
];
